class AbstractRenderer {
    const ERROR_TRACKING_CATEGORY = 'communityrequests-error-category';

    protected function getErrorMessage($msg, $element = 'p') {
        return Html::element($element, ['class' => 'error'], $msg);
    }

    protected function getMissingFieldsErrorMessage($missingFields) {
        return $this->msg('communityrequests-error-missing-fields', $missingFields)->text();
    }

    protected function getValidatedMessage($message, $defaultMessage = null) {
        return $message ?: $defaultMessage;
    }

    public function render($wikitextVal) {
        $this->parser->addTrackingCategory(self::ERROR_TRACKING_CATEGORY);

        if (empty($wikitextVal)) {
            $error = $this->getErrorMessage($this->msg('communityrequests-error-missing-status')->text());
        } else {
            $error = $this->getErrorMessage($this->msg('communityrequests-error-invalid-status', $wikitextVal)->text());
        }

        return $error;
    }
}
