class CodeMirrorLint {
    private request: Promise<any> | null = null;

    async lint(doc: any) {
        if (this.request) {
            this.request.catch(() => {});
            this.request = null;
        }

        try {
            this.request = rest.post('/v1/transform/wikitext/to/lint', {
                wikitext: doc.toString()
            });

            const errors = await this.request;
            mw.log.warn('[CodeMirror] Lint request completed successfully.');
            return errors;
        } catch (error) {
            mw.log.warn('[CodeMirror] Lint request failed:', error);
            throw error;
        } finally {
            this.request = null;
        }
    }
}

export default CodeMirrorLint;
