private function isDeepWebScrapingRequest(): bool {
	// Request issued via web. We could consider api requests, but the
	// no cookie signal is only useful in the web context.
	if ( MW_ENTRY_POINT !== 'web' ) {
		return false;
	}
	// Request has no cookies (bot signal). Note that WebRequest doesn't
	// have a way to ask if cookies exist, the api only allows asking about
	// named cookies.  So we use the php globals that webrequest delegates to.
	if ( count( $_COOKIE ) > 0 ) {
		return false;
	}
	// Check if the request has cookies using the WebRequest method
	if ( $this->webrequest->getHeader( 'Cookie' ) ) {
		return false;
	}
	return true;
}
