class Permissions {
    private $permissions = [];

    public function isEmpty(): bool {
        return count($this->permissions) === 0;
    }

    public function getPermissions(): array {
        return $this->permissions;
    }
}

class TestingAccessWrapper {
    private $permissions;

    public static function newFromObject($permissions): TestingAccessWrapper {
        $wrapper = new TestingAccessWrapper();
        $wrapper->permissions = $permissions;
        return $wrapper;
    }

    public function getPermissions(): array {
        return $this->permissions;
    }
}

class TestPermissions extends PHPUnit\Framework\TestCase {
    public function testPermissionsIsEmpty() {
        $pager = new Permissions();
        $externalPermissions = TestingAccessWrapper::newFromObject($pager->getPermissions());
        $this->assertTrue($externalPermissions->isEmpty());
    }
}
